import numpy as np,time,json
root=Path('/output')
(root/'fit_hmm.py').write_text('''import numpy as np,time

def softmax(a):
 a=a-a.max(axis=-1,keepdims=True);v=np.exp(a);return v/v.sum(axis=-1,keepdims=True)

def predict(params,x,cache=False):
 pi,A,E=[softmax(v) for v in params];N,T=x.shape;K=len(pi)
 b=np.empty((T+1,N,K));u=np.empty((T,N,K));z=np.empty((T,N,1));q=np.empty((N,T,E.shape[1]));b[0]=pi
 for t in range(T):
  q[:,t]=b[t]@E
  v=b[t]*E[:,x[:,t]].T;z[t]=v.sum(1,keepdims=True);u[t]=v/z[t];b[t+1]=u[t]@A
 return (q,(pi,A,E,b,u,z)) if cache else q

def lossgrad(params,x,p):
 q,c=predict(params,x,True);pi,A,E,b,u,z=c;N,T=x.shape
 loss=-np.sum(p*np.log(q))/(N*T);dq=-p/q/(N*T)
 ge=np.zeros_like(E);ga=np.zeros_like(A);gb=np.zeros_like(b[0])
 for t in range(T-1,-1,-1):
  if t<T-1:
   ga+=u[t].T@gb
   du=gb@A.T;dv=(du-(du*u[t]).sum(1,keepdims=True))/z[t]
   for a in range(E.shape[1]):
    ix=x[:,t]==a
    if ix.any():ge[:,a]+=(dv[ix]*b[t,ix]).sum(0)
   gb=dv*E[:,x[:,t]].T
  else:gb=np.zeros_like(gb)
  ge+=b[t].T@dq[:,t];gb+=dq[:,t]@E.T
 gp=gb.sum(0)
 grads=[]
 for v,g in zip([pi,A,E],[gp,ga,ge]):grads.append(v*(g-(g*v).sum(axis=-1,keepdims=True)))
 return loss,grads

def kl(p,q):return float(np.mean(np.sum(p*np.log(p/np.maximum(q,1e-30)),axis=-1)))

def init(k,p,seed):
 rng=np.random.default_rng(seed);Q=p.reshape(-1,16);E=rng.random((k,16));W=rng.random((len(Q),k))
 for _ in range(600):
  W*=(Q@E.T)/(W@E@E.T+1e-20);E*=(W.T@Q)/(W.T@W@E+1e-20);n=E.sum(1);E/=n[:,None];W*=n
 E=(E+0.002)/(1+16*0.002);A=.86*np.eye(k)+.14/k;pi=np.ones(k)/k
 return [np.log(pi),np.log(A),np.log(E)]

def fit(k,x,p,xt,pt,steps=1800,seed=11,params=None,lr=.025):
 params=init(k,p,seed) if params is None else [v.copy() for v in params]
 m=[np.zeros_like(v) for v in params];s=[v.copy() for v in m];best=1e9;bst=None;start=time.time()
 for it in range(1,steps+1):
  loss,g=lossgrad(params,x,p)
  rate=lr*(.3+.7*(1-it/steps))
  for j in range(3):
   m[j]=.9*m[j]+.1*g[j];s[j]=.999*s[j]+.001*g[j]**2
   params[j]-=rate*(m[j]/(1-.9**it))/(np.sqrt(s[j]/(1-.999**it))+1e-8)
  if it%100==0 or it==1:
   val=kl(pt,predict(params,xt))
   if val<best:best=val;bst=[v.copy() for v in params]
 return bst,{'k':k,'steps':steps,'seed':seed,'train_kl':kl(p,predict(bst,x)),'validation_kl':best,'seconds':time.time()-start}
''')
