 b=np.empty((T+1,N,K));v=np.empty((T,N,K));z=np.empty((T,N,1));q=np.empty((N,T,R.shape[1]));b[0]=pi
 for t in range(T):
  q[:,t]=b[t]@R;v[t]=b[t]@A
  w=v[t]*L[:,x[:,t]].T;z[t]=w.sum(1,keepdims=True);b[t+1]=w/z[t]
 return (q,(pi,A,L,R,b,v,z)) if cache else q

def lossgrad(params,x,p):
 q,c=predict(params,x,True);pi,A,L,R,b,v,z=c;N,T=x.shape
 loss=-np.sum(p*np.log(q))/(N*T);dq=-p/q/(N*T)
 gr=np.zeros_like(R);gl=np.zeros_like(L);ga=np.zeros_like(A);gb=np.zeros_like(b[0])
 for t in range(T-1,-1,-1):
  if t<T-1:
   dw=(gb-(gb*b[t+1]).sum(1,keepdims=True))/z[t]
   for a in range(L.shape[1]):
    ix=x[:,t]==a
    if ix.any():gl[:,a]+=(dw[ix]*v[t,ix]).sum(0)
   dv=dw*L[:,x[:,t]].T;ga+=b[t].T@dv;gb=dv@A.T
  else:gb=np.zeros_like(gb)
  gr+=b[t].T@dq[:,t];gb+=dq[:,t]@R.T
 gp=gb.sum(0);grads=[]
 for w,g in zip([pi,A,L,R],[gp,ga,gl,gr]):grads.append(w*(g-(g*w).sum(axis=-1,keepdims=True)))
 return loss,grads

def fit(params,x,p,xt,pt,steps=5000,lr=.015):
 params=[v.copy() for v in params];m=[np.zeros_like(v) for v in params];s=[v.copy() for v in m];best=1e9;bst=None;start=time.time()
 for it in range(1,steps+1):
  loss,g=lossgrad(params,x,p);rate=lr*(.3+.7*(1-it/steps))
  for j in range(4):
   m[j]=.9*m[j]+.1*g[j];s[j]=.999*s[j]+.001*g[j]**2
   params[j]-=rate*(m[j]/(1-.9**it))/(np.sqrt(s[j]/(1-.999**it))+1e-8)
  if it%100==0 or it==1:
